package com.tihai.utils;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import java.io.*;import static org.junit.jupiter.api.Assertions.*;
class AccountIsolationTest {
 @TempDir Path root;@AfterEach void clear()throws Exception{AccountScope.clear();WindowsTestCleanup.remove(root);}
 Map<String,Object> account(AccountRegistry registry,String raw)throws Exception{String id=registry.registerChaoxing(raw,false);return registry.lookup(id);}
 @Test void selectedPlatformAndAccountPersistWithoutExposingLoginSecrets()throws Exception{AccountRegistry r=new AccountRegistry(root);Map a=account(r,"13800000001"),b=account(r,"13800000002");r.select("chaoxing",String.valueOf(b.get("id")));Map d=new AccountRegistry(root).view();assertEquals(b.get("id"),((Map)d.get("selected")).get("chaoxing"));for(Object row:(List)d.get("accounts")){assertFalse(((Map)row).containsKey("account"));assertFalse(((Map)row).containsKey("password"));}assertNotEquals(a.get("id"),b.get("id"));}
 @Test void actionOwnershipSurvivesDeletionOfOriginalQueueAndRestart()throws Exception{AccountRegistry r=new AccountRegistry(root);Map a=account(r,"account-a"),b=account(r,"account-b");r.attachTask("task-a",String.valueOf(a.get("id")));r.resource("exam","exam-b","account-b");r=new AccountRegistry(root);AccountScope.bind(a);assertTrue(r.ownsTask("task-a"));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->new AccountRegistry(root).requireResource("exam","exam-b"));AccountScope.bind(b);assertFalse(r.ownsTask("task-a"));assertTrue(r.ownsResource("exam","exam-b"));}
 @Test void platformAndAccountCannotBeMixedAndEmptySelectionNeverMeansAllAccounts()throws Exception{AccountRegistry r=new AccountRegistry(root);Map a=account(r,"account-a");Map rain=r.addRain("雨课堂A","https://www.yuketang.cn/");assertThrows(IllegalArgumentException.class,()->r.resolve("chaoxing",String.valueOf(rain.get("id"))));AccountScope.bind(r.resolve("yuketang",String.valueOf(rain.get("id"))));assertFalse(AccountScope.allows("account-a"));AccountScope.bind(r.resolve("chaoxing",String.valueOf(a.get("id"))));assertTrue(AccountScope.allows("account-a"));assertFalse(AccountScope.allows("account-b"));}
 @Test void automaticSigninSettingsAreIndependentPerAccount()throws Exception{AccountRegistry r=new AccountRegistry(root);Map a=account(r,"a"),b=account(r,"b");SigninStore s=new SigninStore(root);AccountScope.bind(a);s.settings(true,Arrays.asList("a-course"));AccountScope.bind(b);assertEquals(false,s.settings().get("autoNormal"));s.settings(false,Arrays.asList("b-course"));AccountScope.bind(a);assertEquals(true,s.settings().get("autoNormal"));assertEquals(Arrays.asList("a-course"),s.settings().get("courseKeys"));AccountScope.bind(b);assertEquals(Arrays.asList("b-course"),new SigninStore(root).settings().get("courseKeys"));}
 @Test void rainTasksUseIndependentAccountAndModuleAndDenyForeignOperations()throws Exception{RainStore s=new RainStore(root);Map a=s.add("a","同名课程","https://www.yuketang.cn/v2/web/studentLog/1","chapters");Map b=s.add("b","同名课程","https://www.yuketang.cn/v2/web/studentLog/1","homework");assertNotEquals(a.get("id"),b.get("id"));assertEquals(1,s.list("a","chapters").size());assertTrue(s.list("a","homework").isEmpty());assertThrows(IOException.class,()->s.task(String.valueOf(b.get("id")),"a"));assertThrows(IOException.class,()->s.delete(String.valueOf(b.get("id")),"a"));assertEquals(1,new RainStore(root).list("b","homework").size());}
 @Test void interruptedRainTasksRecoverStoppedInsteadOfResubmitting()throws Exception{RainStore s=new RainStore(root);Map t=s.add("a","课","https://changjiang.yuketang.cn/pro/lms/1/studycontent","chapters");String id=String.valueOf(t.get("id"));s.update(id,"a",Collections.singletonMap("state","running"));assertThrows(IOException.class,()->s.delete(id,"a"));RainStore reopened=new RainStore(root);assertEquals("stopped",reopened.task(id,"a").get("state"));assertEquals(false,reopened.task(id,"a").get("autoSubmit"));}
 @Test void urlsCannotEscapeAllowedPlatformOrInjectCredentials()throws Exception{for(String u:Arrays.asList("http://www.yuketang.cn/","https://yuketang.cn.example.org/","https://user:secret@www.yuketang.cn/","https://localhost/","file:///D:/secret","https://www.yuketang.cn:443/"))assertThrows(IOException.class,()->RainStore.validate(u,false));assertThrows(IOException.class,()->RainStore.validate("https://www.yuketang.cn/",true));assertEquals("https://abc.yuketang.cn/v2/web/studentLog/12",RainStore.validate("https://abc.yuketang.cn/v2/web/studentLog/12",true));}
 @Test void twoRainLoginsNeverReuseSameProfileIdAndLoginMustBeVerified()throws Exception{AccountRegistry r=new AccountRegistry(root);Map a=r.addRain("A","https://www.yuketang.cn/"),b=r.addRain("B","https://www.yuketang.cn/");assertNotEquals(a.get("id"),b.get("id"));assertEquals(false,a.get("verified"));r.verified(String.valueOf(a.get("id")),"identity-a");assertThrows(IOException.class,()->r.verified(String.valueOf(b.get("id")),"identity-a"));assertEquals(false,r.lookup(String.valueOf(b.get("id"))).get("verified"));}
}
